%[text] # Vehicle Speed Reference - Simulation Case
model_name = "HarnessModel_VehSpdRef";
load_system(model_name)

sim_in = Simulink.SimulationInput(model_name);
sim_in = setBlockParameter(sim_in, gcs + "/Vehicle speed reference", ReferencedSubsystem = "VehSpdRef_Constant_refsub");
sim_in = setModelParameter(sim_in, StopTime = "100");
applyToModel(sim_in)

sim_out = sim(sim_in);

sim_data = extractTimetable(sim_out.logsout);

bev1mus.SignalUtil.plotTimedData( ... %[output:group:62641bf3] %[output:9719dc5c]
  TimedData = sim_data, ... %[output:9719dc5c]
  SignalName = "Vehicle speed reference kph", ... %[output:9719dc5c]
  FigureHeight = 150 ) %[output:group:62641bf3] %[output:9719dc5c]
